budget.value:
fun p =>
  have Λ := min p.L p.Lhat;
  have A := 1 + Λ * p.Δ / p.ε ^ 2;
  have H := Finset.univ.sup p.h + p.l + 64 * p.b;
  have V := p.Lhat / √↑↑p.n;
  have s := 2 + Real.log (1 + p.Δ * (Λ + V) / p.ε ^ 2) + Real.log (1 + Real.log (↑↑p.n * ↑↑p.d));
  have t := 1 + Real.log (1 + Real.log (↑↑p.d * A));
  have P :=
    s * (1 + p.Δ * (Λ + ↑↑p.d * min Λ V) / p.ε ^ 2) +
      ↑↑p.d *
        min (p.G / (p.ε * √↑↑p.n) * √(s * t))
          (min (t + Real.log (1 + p.G ^ 2 * s / (↑↑p.n * p.ε ^ 2))) (1 + Real.log (↑↑p.n * ↑↑p.d * A)));
  2 ^ 22 *
    if min (2 * Λ * p.Δ) (p.G ^ 2) ≤ p.ε ^ 2 then 0
    else
      if p.n = 1 then A.toNNReal * (H + p.b * ↑↑p.d * (2 + Real.log A + Real.log (1 + Real.log ↑↑p.d)).toNNReal)
      else A.toNNReal * H + p.b * P.toNNReal

